KG42.register("nodes-bb58e9cb638ec773504e561d",{"id":"COMP-51f1ed6d657e2673","code":"PRC031","label":"Uniform balance-dual prices differentiated by time, energy carrier and location","definition":"For each time period, carrier, and pricing location (t,e,l), determine a uniform unit price λ_{t,e,l} compatible with the clearing outcome; under linearity and when variables take continuous closed-interval values, this price is obtained from the shadow price of the corresponding power balance constraint (12).","layer":"L6","template_code":"DA","concept_id":"pricing.local","concept_ids":["pricing.local"],"identity_dimensions":{"identity_fields":["Object: unit price of energy corresponding to a time period, carrier, and location","Core relationship: the clearing price is obtained from the dual shadow price of the corresponding balance constraint","Output: uniform market price λ_{t,e,l} applicable to the same (t,e,l)"]},"exclusions":["Prices for different carriers need not be equal; under network congestion, location prices reflect their respective marginal values","Under AND or OR bid dependencies, the balance-constraint shadow price is still used","In the absence of network constraints and bid dependencies, the price equals the valuation of the highest-valued accepted supply bid or the highest-valued rejected demand bid, depending on which bid is marginal","The unit is €/kWh; the evidence does not specify the sign range of the market price"],"members":[{"id":"48-multiple_energy_carrier_market::v141-c-R007::V::pricing.local","rule_id":"v141-c-R007","market_meaning":"The local clearing price equals the valuation contained in the highest-valued rejected demand bid when that bid is marginal. Scope: Marginal-bid price determination in the local auction. Condition: There are no network constraints or bid dependencies, and the highest-valued rejected demand bid is marginal. The local clearing price equals the valuation contained in the highest-valued accepted supply bid when that bid is marginal. Scope: Marginal-bid price determination in the local auction. Condition: There are no network constraints or bid dependencies, and the highest-valued accepted supply bid is marginal. Local market clearing outputs market prices that must be compatible with its cleared-bid solution. Scope: Outputs of the proposed local multi-energy-carrier market clearing. The local market operator determines one uniform clearing price for each time-period, energy carrier and pricing location. Scope: Uniform pricing within each time-period, energy carrier and pricing location of the local market. Local clearing prices need not be equal across energy carriers, even when the carriers are cleared simultaneously. Scope: Prices for energy carriers cleared simultaneously in the local market. Prices at the local market's pricing locations adjust to reflect the marginal value of energy at each location. Scope: Energy-carrier-specific pricing locations within the local market. Condition: Network congestion occurs. Local clearing prices can be obtained from the shadow prices of the power-balance constraints. Scope: Recovery of local clearing prices from the proposed optimization formulation. Condition: The optimization problem is linear and its variables take values on a closed interval of real numbers. Shadow prices continue to provide appropriate local market clearing prices when bids have AND- or OR-dependencies. Scope: Shadow-price recovery of prices in the local market with linked bids. Condition: Bids are connected with AND-dependencies or OR-dependencies. The shadow prices of the power-balance constraints differ across pricing locations. Scope: Prices across pricing locations within the local market. Condition: Network limitations are implemented.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"pricing","context_text":"Energy-carrier-specific pricing locations within the local market. | Marginal-bid price determination in the local auction. | Outputs of the proposed local multi-energy-carrier market clearing. | Prices across pricing locations within the local market. | Prices for energy carriers cleared simultaneously in the local market. | Recovery of local clearing prices from the proposed optimization formulation. | Shadow-price recovery of prices in the local market with linked bids. | Uniform pricing within each time-period, energy carrier and pricing location of the local market.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E009","v141-b-g01-E010","v141-b-g01-E015","v141-b-g01-E021","v141-b-g01-E022","v141-b-g01-E040","v141-b-g01-E041","v141-b-g01-E042","v141-b-g01-E043"]},"constraint_refs":["48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C001","48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C002","48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C003","48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C004","48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C005","48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C006","48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C007","48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C008","48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C009"],"decision_anchor":"pricing.local","source_rule_sha256":"cebe08bdbd281691f3dc4d810d593fac07465ea6e3f0aea76ccec7c989aa2a8e","paper":"48-multiple_energy_carrier_market","rule_ref":"48-multiple_energy_carrier_market::v141-c-R007","node_id":"pricing.local","function":"pricing.local","unit_id":"48-multiple_energy_carrier_market::v141-a-M01::pricing.local","mechanism_id":"v141-a-M01","anchor":true},{"id":"48-multiple_energy_carrier_market::v141-c-R009::V::pricing.local","rule_id":"v141-c-R009","market_meaning":"Local market clearing supplies its binding-hour results to financial settlement; results for subsequent hours are not used for settlement. Scope: Financial settlement in the proposed local multi-energy-carrier market. Condition: Only results for the first hour of the trading horizon, the binding hour, are used. The local market clearing price determines the amount paid or received for accepted bids under uniform pricing, rather than their bid valuations. Scope: Uniform-price financial settlement of accepted bids in the proposed local multi-energy-carrier market. Condition: Financial settlement uses only binding-hour results.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Financial settlement in the proposed local multi-energy-carrier market. | Uniform-price financial settlement of accepted bids in the proposed local multi-energy-carrier market.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E009","v141-b-g01-E016","v141-b-g03-E01"]},"constraint_refs":["48-multiple_energy_carrier_market::v141-c-R009::v141-c-R009-C002"],"decision_anchor":"settlement.payment","source_rule_sha256":"95defbedaee354b8d96e4535e94ff19d1ca5c28155209150c2ac68ff99c0753d","paper":"48-multiple_energy_carrier_market","rule_ref":"48-multiple_energy_carrier_market::v141-c-R009","node_id":"pricing.local","function":"pricing.local","unit_id":"48-multiple_energy_carrier_market::v141-a-M01::pricing.local","mechanism_id":"v141-a-M01","anchor":false}],"paper_ids":["48-multiple_energy_carrier_market"],"evidence":[{"evidence_id":"v141-b-g01-E015","location":{"location_id":"src-ec182c21f1-p04-c1r2__v141-a-M01-bidding","page":4,"printed_page":null,"section":null,"anchor_text":"energy will be injected or withdrawn). In addition, each bid states a 4. single quantity (in kWh) an","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"In the proposed market design, each individual bid has a very simple structure. Each bid contains basic information about what the bid is for (i.e. it specifies an energy carrier, a delivery-hour, whether it is a supply or demand bid, and the location on the network where the energy will be injected or withdrawn). In addition, each bid states a single quantity (in kWh) and a single valuation (in €/kWh).","paper":"48-multiple_energy_carrier_market","rule_id":"v141-c-R007","quote":"In the proposed market design, each individual bid has a very simple structure. Each bid contains basic information about what the bid is for (i.e. it specifies an energy carrier, a delivery-hour, whether it is a supply or demand bid, and the location on the network where the energy will be injected or withdrawn). In addition, each bid states a single quantity (in kWh) and a single valuation (in €/kWh)."},{"evidence_id":"v141-b-g01-E042","location":{"location_id":"src-ec182c21f1-p05-c2r3__v141-a-M01-pricing","page":5,"printed_page":null,"section":null,"anchor_text":"al ( y y), j o- have preferred to trade (they are out-of-the-money). The market clearing prices can ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"In a simple case where there are no network constraints and no bid dependencies, the shadow price for a power balance constraint equals the valuation of the highest-valued accepted supply bid, or the highest-valued rejected demand bid, depending on which is marginal. Therefore, the shadow prices are market clearing in this simple case.","paper":"48-multiple_energy_carrier_market","rule_id":"v141-c-R007","quote":"In a simple case where there are no network constraints and no bid dependencies, the shadow price for a power balance constraint equals the valuation of the highest-valued accepted supply bid, or the highest-valued rejected demand bid, depending on which is marginal. Therefore, the shadow prices are market clearing in this simple case."},{"evidence_id":"v141-b-g01-E022","location":{"location_id":"src-ec182c21f1-p04-c2r1__v141-a-M01-clearing","page":4,"printed_page":null,"section":null,"anchor_text":"Electrical Power and Energy Systems 118 (2020) 105739 re 4.2. Market clearing and pricing re This se","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"This section provides a mathematical description of the market clearing mechanism, including all the main ingredients discussed in Section 4.1. The market clearing is based on mathematical optimization, where the objective is to maximize the sum of consumer and producer surplus. The problem is kept linear, which means that it can be solved efficiently using available linear programming (LP) software. Input to the market clearing problem consists of bids and bid dependencies, and outputs are the cleared bid quantities and market prices.","paper":"48-multiple_energy_carrier_market","rule_id":"v141-c-R007","quote":"This section provides a mathematical description of the market clearing mechanism, including all the main ingredients discussed in Section 4.1. The market clearing is based on mathematical optimization, where the objective is to maximize the sum of consumer and producer surplus. The problem is kept linear, which means that it can be solved efficiently using available linear programming (LP) software. Input to the market clearing problem consists of bids and bid dependencies, and outputs are the cleared bid quantities and market prices."},{"evidence_id":"v141-b-g01-E040","location":{"location_id":"src-ec182c21f1-p05-c2r3__v141-a-M01-pricing","page":5,"printed_page":null,"section":null,"anchor_text":"al ( y y), j o- have preferred to trade (they are out-of-the-money). The market clearing prices can ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"The solution to the market optimization problem determines which bids should be accepted and which should be rejected. This is done without introducing any price variables into the optimization problem. However, the market operator needs to determine one price for each time-period, energy carrier, and pricing location. In a general microeconomic sense, a price is considered to clear a market if, at that price, the total amount that producers would like to sell equals the total amount that consumers would like to buy. Hence, the market operator needs to find market clearing prices that are compatible with the optimization problem solution so that all accepted bids should be willing to trade (they are in-the-money), and none of the rejected bids would have preferred to trade (they are out-of-the-money).","paper":"48-multiple_energy_carrier_market","rule_id":"v141-c-R007","quote":"The solution to the market optimization problem determines which bids should be accepted and which should be rejected. This is done without introducing any price variables into the optimization problem. However, the market operator needs to determine one price for each time-period, energy carrier, and pricing location. In a general microeconomic sense, a price is considered to clear a market if, at that price, the total amount that producers would like to sell equals the total amount that consumers would like to buy. Hence, the market operator needs to find market clearing prices that are compatible with the optimization problem solution so that all accepted bids should be willing to trade (they are in-the-money), and none of the rejected bids would have preferred to trade (they are out-of-the-money)."},{"evidence_id":"v141-b-g01-E009","location":{"location_id":"src-ec182c21f1-p03-c2r2__v141-a-M01-clearing","page":3,"printed_page":null,"section":null,"anchor_text":", g p production bids are part of the same market clearing. The market op- al erator ensures that to","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"The auction is a uniform price auction, meaning that all accepted bids pay or receive a market price.","paper":"48-multiple_energy_carrier_market","rule_id":"v141-c-R007","quote":"The auction is a uniform price auction, meaning that all accepted bids pay or receive a market price."},{"evidence_id":"v141-b-g01-E002","location":{"location_id":"src-ec182c21f1-p02-c2r1__v141-a-M01-pricing","page":2,"printed_page":null,"section":null,"anchor_text":"Electrical Power and Energy Systems 118 (2020) 105739 L0 set of reference locations, L0 ⊂ L Ll set o","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"L^0 set of reference locations, L^0 ⊂ L; L^l set of locations connected to pricing location l; v_{b,t,e,l} bid valuation [€/kWh]; q_{b,t,e,l} bid quantity [kWh]; Q_r total quantity for bid dependency [kWh]; y_{b,t,e,l} amount cleared from bid [kWh]; a_{l,k} admittance between locations [kW]; c_{l,k} transfer limit [kW]; inj_{t,e,l} net energy injection [kW]; flo_{t,e,l} net energy outflow [kW]; ang_{t,e,l} voltage angle [·]; λ_{t,e,l} market clearing price [€/kWh].","paper":"48-multiple_energy_carrier_market","rule_id":"v141-c-R007","quote":"L^0 set of reference locations, L^0 ⊂ L; L^l set of locations connected to pricing location l; v_{b,t,e,l} bid valuation [€/kWh]; q_{b,t,e,l} bid quantity [kWh]; Q_r total quantity for bid dependency [kWh]; y_{b,t,e,l} amount cleared from bid [kWh]; a_{l,k} admittance between locations [kW]; c_{l,k} transfer limit [kW]; inj_{t,e,l} net energy injection [kW]; flo_{t,e,l} net energy outflow [kW]; ang_{t,e,l} voltage angle [·]; λ_{t,e,l} market clearing price [€/kWh]."},{"evidence_id":"v141-b-g01-E010","location":{"location_id":"src-ec182c21f1-p03-c2r2__v141-a-M01-clearing","page":3,"printed_page":null,"section":null,"anchor_text":", g p production bids are part of the same market clearing. The market op- al erator ensures that to","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"In the proposed market design, energy is traded for multiple energy carriers simultaneously. Although different energy carriers are traded simultaneously as part of the same market clearing, they are still treated as separate commodities, and the market clearing prices are not necessarily equal across energy carriers.","paper":"48-multiple_energy_carrier_market","rule_id":"v141-c-R007","quote":"In the proposed market design, energy is traded for multiple energy carriers simultaneously. Although different energy carriers are traded simultaneously as part of the same market clearing, they are still treated as separate commodities, and the market clearing prices are not necessarily equal across energy carriers."},{"evidence_id":"v141-b-g01-E021","location":{"location_id":"src-ec182c21f1-p04-c1r4__v141-a-M01-pricing","page":4,"printed_page":null,"section":null,"anchor_text":"st th4.1.5. Network constraints The suggested market design takes network transfer limitations expli","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"The suggested market design takes network transfer limitations explicitly into account when clearing the market. The purpose of this is to prevent the market from clearing a combination of bids that would lead to energy flows that the local distribution networks cannot handle. This is achieved by subdividing the local market into pricing locations, which are defined such that the most important network constraints can be captured as transfer limits between the different locations. The pricing locations are energy carrier-specific, since the appropriate pricing location definitions may be different for different energy carriers. In case of network congestion, the market prices at the various pricing locations will adjust to reflect the marginal value of energy in every pricing location. Hence, the principle of nodal pricing as presented in e.g. [38] is applied, and extended to incorporate different energy carriers.","paper":"48-multiple_energy_carrier_market","rule_id":"v141-c-R007","quote":"The suggested market design takes network transfer limitations explicitly into account when clearing the market. The purpose of this is to prevent the market from clearing a combination of bids that would lead to energy flows that the local distribution networks cannot handle. This is achieved by subdividing the local market into pricing locations, which are defined such that the most important network constraints can be captured as transfer limits between the different locations. The pricing locations are energy carrier-specific, since the appropriate pricing location definitions may be different for different energy carriers. In case of network congestion, the market prices at the various pricing locations will adjust to reflect the marginal value of energy in every pricing location. Hence, the principle of nodal pricing as presented in e.g. [38] is applied, and extended to incorporate different energy carriers."},{"evidence_id":"v141-b-g01-E041","location":{"location_id":"src-ec182c21f1-p05-c2r3__v141-a-M01-pricing","page":5,"printed_page":null,"section":null,"anchor_text":"al ( y y), j o- have preferred to trade (they are out-of-the-money). The market clearing prices can ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The market clearing prices can here be obtained by applying the duality property of LP problems, i.e. a primal problem \\max c^T x, \\; \\text{s.t. } Ax \\leqslant b, x \\geqslant 0 is associated with a dual problem \\min b^T \\lambda, \\; \\text{s.t. } A^T \\lambda \\geqslant c, \\lambda \\geqslant 0. The variables \\lambda are the dual variables or shadow prices, reflecting the marginal impact on the objective function value of an incremental change in the right-hand-side of the constraints in the primal problem for the optimal solution [39]. This property can be applied in the described market design since the optimization problem is linear and the variables take on values on a closed interval of real numbers. Under these conditions, market clearing prices can be obtained from the shadow prices for the power balance constraints in (12).","paper":"48-multiple_energy_carrier_market","rule_id":"v141-c-R007","quote":"The market clearing prices can here be obtained by applying the duality property of LP problems, i.e. a primal problem \\max c^T x, \\; \\text{s.t. } Ax \\leqslant b, x \\geqslant 0 is associated with a dual problem \\min b^T \\lambda, \\; \\text{s.t. } A^T \\lambda \\geqslant c, \\lambda \\geqslant 0. The variables \\lambda are the dual variables or shadow prices, reflecting the marginal impact on the objective function value of an incremental change in the right-hand-side of the constraints in the primal problem for the optimal solution [39]. This property can be applied in the described market design since the optimization problem is linear and the variables take on values on a closed interval of real numbers. Under these conditions, market clearing prices can be obtained from the shadow prices for the power balance constraints in (12)."},{"evidence_id":"v141-b-g01-E036","location":{"location_id":"src-ec182c21f1-p05-c1r4__v141-a-M01-clearing","page":5,"printed_page":null,"section":null,"anchor_text":"(angt , e , l angt , e , k ) al , k ⩽ c l , k , C ∀ t ∈ T , e ∈ E , l ∈ L , k ∈ Ll . (11) al pe Fina","equation_id":"(12)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"Finally, power balance constraints ensure that net injection equals net outflow in each pricing location (this will also ensure that total supply equals total demand, for each time-period and energy carrier): inj_{t,e,l} = flo_{t,e,l}, \\quad \\forall t \\in T, e \\in E, l \\in L. \\tag{12}","paper":"48-multiple_energy_carrier_market","rule_id":"v141-c-R007","quote":"Finally, power balance constraints ensure that net injection equals net outflow in each pricing location (this will also ensure that total supply equals total demand, for each time-period and energy carrier): inj_{t,e,l} = flo_{t,e,l}, \\quad \\forall t \\in T, e \\in E, l \\in L. \\tag{12}"},{"evidence_id":"v141-b-g01-E043","location":{"location_id":"src-ec182c21f1-p05-c2r4__v141-a-M01-pricing","page":5,"printed_page":null,"section":null,"anchor_text":"Crucially, the shadow prices provide appropriate market clearing prices also when bids are connected","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"Crucially, the shadow prices provide appropriate market clearing prices also when bids are connected with AND-dependencies or OR-dependencies. In these cases, an individual bid may be accepted even if it is out-of-the-money, but only if other bids in the same dependency compensate for it, such that the dependency altogether is in-the-money. Further, when network limitations are implemented, the shadow prices for the power balance constraints will differ across pricing locations, and each accepted bid will be in-the-money relative to the price at its pricing location.","paper":"48-multiple_energy_carrier_market","rule_id":"v141-c-R007","quote":"Crucially, the shadow prices provide appropriate market clearing prices also when bids are connected with AND-dependencies or OR-dependencies. In these cases, an individual bid may be accepted even if it is out-of-the-money, but only if other bids in the same dependency compensate for it, such that the dependency altogether is in-the-money. Further, when network limitations are implemented, the shadow prices for the power balance constraints will differ across pricing locations, and each accepted bid will be in-the-money relative to the price at its pricing location."},{"evidence_id":"v141-b-g01-E009","location":{"location_id":"src-ec182c21f1-p03-c2r2__v141-a-M01-clearing","page":3,"printed_page":null,"section":null,"anchor_text":", g p production bids are part of the same market clearing. The market op- al erator ensures that to","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"The auction is a uniform price auction, meaning that all accepted bids pay or receive a market price.","paper":"48-multiple_energy_carrier_market","rule_id":"v141-c-R009","quote":"The auction is a uniform price auction, meaning that all accepted bids pay or receive a market price."},{"evidence_id":"v141-b-g01-E016","location":{"location_id":"src-ec182c21f1-p04-c1r2__v141-a-M01-pricing","page":4,"printed_page":null,"section":null,"anchor_text":"energy will be injected or withdrawn). In addition, each bid states a 4. single quantity (in kWh) an","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"The term valuation is here used for the bid parameter instead of the term price to distinguish it from the prices that are obtained from the market clearing process. Since the financial compensation is based on uniform pricing, the amount actually payed or received is based on the market price and not on the bid valuation.","paper":"48-multiple_energy_carrier_market","rule_id":"v141-c-R009","quote":"The term valuation is here used for the bid parameter instead of the term price to distinguish it from the prices that are obtained from the market clearing process. Since the financial compensation is based on uniform pricing, the amount actually payed or received is based on the market price and not on the bid valuation."},{"evidence_id":"v141-b-g03-E01","location":{"location_id":"src-ec182c21f1-p08-c2r2__v141-a-M01-settlement","page":8,"printed_page":null,"section":"6.2 Rolling horizon and financial settlement","anchor_text":"p ; p y the market clearing function or having a more complex decision making function of the agents","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"definition"},"source_text":"In the proposed market design, each market clearing returns market results for the full trading horizon. However, only the results for the first hour in the horizon, the binding hour, is used for financial settlement.","paper":"48-multiple_energy_carrier_market","rule_id":"v141-c-R009","quote":"In the proposed market design, each market clearing returns market results for the full trading horizon. However, only the results for the first hour in the horizon, the binding hour, is used for financial settlement."}],"candidate_only":true,"classification_subtypes":["balance_dual_uniform_pricing"],"projection_statuses":["clear"],"taxonomy":{"primary_family":"kind-L6-842e8d58c7","secondary_families":[],"stage":"L6","ontological_kind":"balance_dual_uniform_pricing"},"semantic_definition":{},"source_units":[{"unit_id":"48-multiple_energy_carrier_market::v141-a-M01::pricing.local","paper_id":"48-multiple_energy_carrier_market","mechanism_id":"v141-a-M01","function":"pricing.local","source_occurrences":[{"id":"48-multiple_energy_carrier_market::v141-c-R007::V::pricing.local","rule_id":"v141-c-R007","market_meaning":"The local clearing price equals the valuation contained in the highest-valued rejected demand bid when that bid is marginal. Scope: Marginal-bid price determination in the local auction. Condition: There are no network constraints or bid dependencies, and the highest-valued rejected demand bid is marginal. The local clearing price equals the valuation contained in the highest-valued accepted supply bid when that bid is marginal. Scope: Marginal-bid price determination in the local auction. Condition: There are no network constraints or bid dependencies, and the highest-valued accepted supply bid is marginal. Local market clearing outputs market prices that must be compatible with its cleared-bid solution. Scope: Outputs of the proposed local multi-energy-carrier market clearing. The local market operator determines one uniform clearing price for each time-period, energy carrier and pricing location. Scope: Uniform pricing within each time-period, energy carrier and pricing location of the local market. Local clearing prices need not be equal across energy carriers, even when the carriers are cleared simultaneously. Scope: Prices for energy carriers cleared simultaneously in the local market. Prices at the local market's pricing locations adjust to reflect the marginal value of energy at each location. Scope: Energy-carrier-specific pricing locations within the local market. Condition: Network congestion occurs. Local clearing prices can be obtained from the shadow prices of the power-balance constraints. Scope: Recovery of local clearing prices from the proposed optimization formulation. Condition: The optimization problem is linear and its variables take values on a closed interval of real numbers. Shadow prices continue to provide appropriate local market clearing prices when bids have AND- or OR-dependencies. Scope: Shadow-price recovery of prices in the local market with linked bids. Condition: Bids are connected with AND-dependencies or OR-dependencies. The shadow prices of the power-balance constraints differ across pricing locations. Scope: Prices across pricing locations within the local market. Condition: Network limitations are implemented.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"pricing","context_text":"Energy-carrier-specific pricing locations within the local market. | Marginal-bid price determination in the local auction. | Outputs of the proposed local multi-energy-carrier market clearing. | Prices across pricing locations within the local market. | Prices for energy carriers cleared simultaneously in the local market. | Recovery of local clearing prices from the proposed optimization formulation. | Shadow-price recovery of prices in the local market with linked bids. | Uniform pricing within each time-period, energy carrier and pricing location of the local market.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E009","v141-b-g01-E010","v141-b-g01-E015","v141-b-g01-E021","v141-b-g01-E022","v141-b-g01-E040","v141-b-g01-E041","v141-b-g01-E042","v141-b-g01-E043"]},"constraint_refs":["48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C001","48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C002","48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C003","48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C004","48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C005","48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C006","48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C007","48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C008","48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C009"],"decision_anchor":"pricing.local","source_rule_sha256":"cebe08bdbd281691f3dc4d810d593fac07465ea6e3f0aea76ccec7c989aa2a8e"},{"id":"48-multiple_energy_carrier_market::v141-c-R009::V::pricing.local","rule_id":"v141-c-R009","market_meaning":"Local market clearing supplies its binding-hour results to financial settlement; results for subsequent hours are not used for settlement. Scope: Financial settlement in the proposed local multi-energy-carrier market. Condition: Only results for the first hour of the trading horizon, the binding hour, are used. The local market clearing price determines the amount paid or received for accepted bids under uniform pricing, rather than their bid valuations. Scope: Uniform-price financial settlement of accepted bids in the proposed local multi-energy-carrier market. Condition: Financial settlement uses only binding-hour results.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Financial settlement in the proposed local multi-energy-carrier market. | Uniform-price financial settlement of accepted bids in the proposed local multi-energy-carrier market.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E009","v141-b-g01-E016","v141-b-g03-E01"]},"constraint_refs":["48-multiple_energy_carrier_market::v141-c-R009::v141-c-R009-C002"],"decision_anchor":"settlement.payment","source_rule_sha256":"95defbedaee354b8d96e4535e94ff19d1ca5c28155209150c2ac68ff99c0753d"}],"constraints":[{"constraint_id":"v141-c-R007-C001","kind":"procedural","role":"core","statement":"The local clearing price equals the valuation contained in the highest-valued rejected demand bid when that bid is marginal. Scope: Marginal-bid price determination in the local auction. Condition: There are no network constraints or bid dependencies, and the highest-valued rejected demand bid is marginal.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand","pricing.local"],"variable_refs":["v141-c-R007-x-lambda"],"parameter_refs":["v141-c-R007-theta-v"],"evidence_ids":["v141-b-g01-E015","v141-b-g01-E042"],"ref":"48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C001","source_rule_id":"v141-c-R007","evidence":[{"evidence_id":"v141-b-g01-E015","location":{"location_id":"src-ec182c21f1-p04-c1r2__v141-a-M01-bidding","page":4,"printed_page":null,"section":null,"anchor_text":"energy will be injected or withdrawn). In addition, each bid states a 4. single quantity (in kWh) an","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"In the proposed market design, each individual bid has a very simple structure. Each bid contains basic information about what the bid is for (i.e. it specifies an energy carrier, a delivery-hour, whether it is a supply or demand bid, and the location on the network where the energy will be injected or withdrawn). In addition, each bid states a single quantity (in kWh) and a single valuation (in €/kWh)."},{"evidence_id":"v141-b-g01-E042","location":{"location_id":"src-ec182c21f1-p05-c2r3__v141-a-M01-pricing","page":5,"printed_page":null,"section":null,"anchor_text":"al ( y y), j o- have preferred to trade (they are out-of-the-money). The market clearing prices can ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"In a simple case where there are no network constraints and no bid dependencies, the shadow price for a power balance constraint equals the valuation of the highest-valued accepted supply bid, or the highest-valued rejected demand bid, depending on which is marginal. Therefore, the shadow prices are market clearing in this simple case."}]},{"constraint_id":"v141-c-R007-C002","kind":"procedural","role":"core","statement":"The local clearing price equals the valuation contained in the highest-valued accepted supply bid when that bid is marginal. Scope: Marginal-bid price determination in the local auction. Condition: There are no network constraints or bid dependencies, and the highest-valued accepted supply bid is marginal.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.supply","pricing.local"],"variable_refs":["v141-c-R007-x-lambda"],"parameter_refs":["v141-c-R007-theta-v"],"evidence_ids":["v141-b-g01-E015","v141-b-g01-E042"],"ref":"48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C002","source_rule_id":"v141-c-R007","evidence":[{"evidence_id":"v141-b-g01-E015","location":{"location_id":"src-ec182c21f1-p04-c1r2__v141-a-M01-bidding","page":4,"printed_page":null,"section":null,"anchor_text":"energy will be injected or withdrawn). In addition, each bid states a 4. single quantity (in kWh) an","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"In the proposed market design, each individual bid has a very simple structure. Each bid contains basic information about what the bid is for (i.e. it specifies an energy carrier, a delivery-hour, whether it is a supply or demand bid, and the location on the network where the energy will be injected or withdrawn). In addition, each bid states a single quantity (in kWh) and a single valuation (in €/kWh)."},{"evidence_id":"v141-b-g01-E042","location":{"location_id":"src-ec182c21f1-p05-c2r3__v141-a-M01-pricing","page":5,"printed_page":null,"section":null,"anchor_text":"al ( y y), j o- have preferred to trade (they are out-of-the-money). The market clearing prices can ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"In a simple case where there are no network constraints and no bid dependencies, the shadow price for a power balance constraint equals the valuation of the highest-valued accepted supply bid, or the highest-valued rejected demand bid, depending on which is marginal. Therefore, the shadow prices are market clearing in this simple case."}]},{"constraint_id":"v141-c-R007-C003","kind":"procedural","role":"core","statement":"Local market clearing outputs market prices that must be compatible with its cleared-bid solution. Scope: Outputs of the proposed local multi-energy-carrier market clearing.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.local","pricing.local"],"variable_refs":["v141-c-R007-x-lambda"],"parameter_refs":[],"evidence_ids":["v141-b-g01-E022","v141-b-g01-E040"],"ref":"48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C003","source_rule_id":"v141-c-R007","evidence":[{"evidence_id":"v141-b-g01-E022","location":{"location_id":"src-ec182c21f1-p04-c2r1__v141-a-M01-clearing","page":4,"printed_page":null,"section":null,"anchor_text":"Electrical Power and Energy Systems 118 (2020) 105739 re 4.2. Market clearing and pricing re This se","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"This section provides a mathematical description of the market clearing mechanism, including all the main ingredients discussed in Section 4.1. The market clearing is based on mathematical optimization, where the objective is to maximize the sum of consumer and producer surplus. The problem is kept linear, which means that it can be solved efficiently using available linear programming (LP) software. Input to the market clearing problem consists of bids and bid dependencies, and outputs are the cleared bid quantities and market prices."},{"evidence_id":"v141-b-g01-E040","location":{"location_id":"src-ec182c21f1-p05-c2r3__v141-a-M01-pricing","page":5,"printed_page":null,"section":null,"anchor_text":"al ( y y), j o- have preferred to trade (they are out-of-the-money). The market clearing prices can ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"The solution to the market optimization problem determines which bids should be accepted and which should be rejected. This is done without introducing any price variables into the optimization problem. However, the market operator needs to determine one price for each time-period, energy carrier, and pricing location. In a general microeconomic sense, a price is considered to clear a market if, at that price, the total amount that producers would like to sell equals the total amount that consumers would like to buy. Hence, the market operator needs to find market clearing prices that are compatible with the optimization problem solution so that all accepted bids should be willing to trade (they are in-the-money), and none of the rejected bids would have preferred to trade (they are out-of-the-money)."}]},{"constraint_id":"v141-c-R007-C004","kind":"procedural","role":"core","statement":"The local market operator determines one uniform clearing price for each time-period, energy carrier and pricing location. Scope: Uniform pricing within each time-period, energy carrier and pricing location of the local market.","expression":"\\forall t\\in T,\\ e\\in E,\\ l\\in L:\\; \\lambda_{t,e,l}\\ \\text{is the single uniform clearing price for }(t,e,l).","formalization_origin":"source","template_id":null,"members":["coordination.local_operator","pricing.local"],"variable_refs":["v141-c-R007-x-lambda"],"parameter_refs":[],"evidence_ids":["v141-b-g01-E009","v141-b-g01-E040","v141-b-g01-E002"],"ref":"48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C004","source_rule_id":"v141-c-R007","evidence":[{"evidence_id":"v141-b-g01-E009","location":{"location_id":"src-ec182c21f1-p03-c2r2__v141-a-M01-clearing","page":3,"printed_page":null,"section":null,"anchor_text":", g p production bids are part of the same market clearing. The market op- al erator ensures that to","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"The auction is a uniform price auction, meaning that all accepted bids pay or receive a market price."},{"evidence_id":"v141-b-g01-E040","location":{"location_id":"src-ec182c21f1-p05-c2r3__v141-a-M01-pricing","page":5,"printed_page":null,"section":null,"anchor_text":"al ( y y), j o- have preferred to trade (they are out-of-the-money). The market clearing prices can ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"The solution to the market optimization problem determines which bids should be accepted and which should be rejected. This is done without introducing any price variables into the optimization problem. However, the market operator needs to determine one price for each time-period, energy carrier, and pricing location. In a general microeconomic sense, a price is considered to clear a market if, at that price, the total amount that producers would like to sell equals the total amount that consumers would like to buy. Hence, the market operator needs to find market clearing prices that are compatible with the optimization problem solution so that all accepted bids should be willing to trade (they are in-the-money), and none of the rejected bids would have preferred to trade (they are out-of-the-money)."},{"evidence_id":"v141-b-g01-E002","location":{"location_id":"src-ec182c21f1-p02-c2r1__v141-a-M01-pricing","page":2,"printed_page":null,"section":null,"anchor_text":"Electrical Power and Energy Systems 118 (2020) 105739 L0 set of reference locations, L0 ⊂ L Ll set o","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"L^0 set of reference locations, L^0 ⊂ L; L^l set of locations connected to pricing location l; v_{b,t,e,l} bid valuation [€/kWh]; q_{b,t,e,l} bid quantity [kWh]; Q_r total quantity for bid dependency [kWh]; y_{b,t,e,l} amount cleared from bid [kWh]; a_{l,k} admittance between locations [kW]; c_{l,k} transfer limit [kW]; inj_{t,e,l} net energy injection [kW]; flo_{t,e,l} net energy outflow [kW]; ang_{t,e,l} voltage angle [·]; λ_{t,e,l} market clearing price [€/kWh]."}]},{"constraint_id":"v141-c-R007-C005","kind":"procedural","role":"core","statement":"Local clearing prices need not be equal across energy carriers, even when the carriers are cleared simultaneously. Scope: Prices for energy carriers cleared simultaneously in the local market.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local"],"variable_refs":["v141-c-R007-x-lambda"],"parameter_refs":[],"evidence_ids":["v141-b-g01-E010"],"ref":"48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C005","source_rule_id":"v141-c-R007","evidence":[{"evidence_id":"v141-b-g01-E010","location":{"location_id":"src-ec182c21f1-p03-c2r2__v141-a-M01-clearing","page":3,"printed_page":null,"section":null,"anchor_text":", g p production bids are part of the same market clearing. The market op- al erator ensures that to","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"In the proposed market design, energy is traded for multiple energy carriers simultaneously. Although different energy carriers are traded simultaneously as part of the same market clearing, they are still treated as separate commodities, and the market clearing prices are not necessarily equal across energy carriers."}]},{"constraint_id":"v141-c-R007-C006","kind":"procedural","role":"core","statement":"Prices at the local market's pricing locations adjust to reflect the marginal value of energy at each location. Scope: Energy-carrier-specific pricing locations within the local market. Condition: Network congestion occurs.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local"],"variable_refs":["v141-c-R007-x-lambda"],"parameter_refs":[],"evidence_ids":["v141-b-g01-E021"],"ref":"48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C006","source_rule_id":"v141-c-R007","evidence":[{"evidence_id":"v141-b-g01-E021","location":{"location_id":"src-ec182c21f1-p04-c1r4__v141-a-M01-pricing","page":4,"printed_page":null,"section":null,"anchor_text":"st th4.1.5. Network constraints The suggested market design takes network transfer limitations expli","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"The suggested market design takes network transfer limitations explicitly into account when clearing the market. The purpose of this is to prevent the market from clearing a combination of bids that would lead to energy flows that the local distribution networks cannot handle. This is achieved by subdividing the local market into pricing locations, which are defined such that the most important network constraints can be captured as transfer limits between the different locations. The pricing locations are energy carrier-specific, since the appropriate pricing location definitions may be different for different energy carriers. In case of network congestion, the market prices at the various pricing locations will adjust to reflect the marginal value of energy in every pricing location. Hence, the principle of nodal pricing as presented in e.g. [38] is applied, and extended to incorporate different energy carriers."}]},{"constraint_id":"v141-c-R007-C007","kind":"mathematical","role":"core","statement":"Local clearing prices can be obtained from the shadow prices of the power-balance constraints. Scope: Recovery of local clearing prices from the proposed optimization formulation. Condition: The optimization problem is linear and its variables take values on a closed interval of real numbers.","expression":"\\lambda_{t,e,l}\\ \\text{is the dual variable (shadow price) associated with the power-balance constraint (12) for }(t,e,l).","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":["v141-c-R007-x-lambda"],"parameter_refs":[],"evidence_ids":["v141-b-g01-E041","v141-b-g01-E002","v141-b-g01-E036"],"ref":"48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C007","source_rule_id":"v141-c-R007","evidence":[{"evidence_id":"v141-b-g01-E041","location":{"location_id":"src-ec182c21f1-p05-c2r3__v141-a-M01-pricing","page":5,"printed_page":null,"section":null,"anchor_text":"al ( y y), j o- have preferred to trade (they are out-of-the-money). The market clearing prices can ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The market clearing prices can here be obtained by applying the duality property of LP problems, i.e. a primal problem \\max c^T x, \\; \\text{s.t. } Ax \\leqslant b, x \\geqslant 0 is associated with a dual problem \\min b^T \\lambda, \\; \\text{s.t. } A^T \\lambda \\geqslant c, \\lambda \\geqslant 0. The variables \\lambda are the dual variables or shadow prices, reflecting the marginal impact on the objective function value of an incremental change in the right-hand-side of the constraints in the primal problem for the optimal solution [39]. This property can be applied in the described market design since the optimization problem is linear and the variables take on values on a closed interval of real numbers. Under these conditions, market clearing prices can be obtained from the shadow prices for the power balance constraints in (12)."},{"evidence_id":"v141-b-g01-E002","location":{"location_id":"src-ec182c21f1-p02-c2r1__v141-a-M01-pricing","page":2,"printed_page":null,"section":null,"anchor_text":"Electrical Power and Energy Systems 118 (2020) 105739 L0 set of reference locations, L0 ⊂ L Ll set o","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"L^0 set of reference locations, L^0 ⊂ L; L^l set of locations connected to pricing location l; v_{b,t,e,l} bid valuation [€/kWh]; q_{b,t,e,l} bid quantity [kWh]; Q_r total quantity for bid dependency [kWh]; y_{b,t,e,l} amount cleared from bid [kWh]; a_{l,k} admittance between locations [kW]; c_{l,k} transfer limit [kW]; inj_{t,e,l} net energy injection [kW]; flo_{t,e,l} net energy outflow [kW]; ang_{t,e,l} voltage angle [·]; λ_{t,e,l} market clearing price [€/kWh]."},{"evidence_id":"v141-b-g01-E036","location":{"location_id":"src-ec182c21f1-p05-c1r4__v141-a-M01-clearing","page":5,"printed_page":null,"section":null,"anchor_text":"(angt , e , l angt , e , k ) al , k ⩽ c l , k , C ∀ t ∈ T , e ∈ E , l ∈ L , k ∈ Ll . (11) al pe Fina","equation_id":"(12)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"Finally, power balance constraints ensure that net injection equals net outflow in each pricing location (this will also ensure that total supply equals total demand, for each time-period and energy carrier): inj_{t,e,l} = flo_{t,e,l}, \\quad \\forall t \\in T, e \\in E, l \\in L. \\tag{12}"}]},{"constraint_id":"v141-c-R007-C008","kind":"procedural","role":"core","statement":"Shadow prices continue to provide appropriate local market clearing prices when bids have AND- or OR-dependencies. Scope: Shadow-price recovery of prices in the local market with linked bids. Condition: Bids are connected with AND-dependencies or OR-dependencies.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local"],"variable_refs":["v141-c-R007-x-lambda"],"parameter_refs":[],"evidence_ids":["v141-b-g01-E043"],"ref":"48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C008","source_rule_id":"v141-c-R007","evidence":[{"evidence_id":"v141-b-g01-E043","location":{"location_id":"src-ec182c21f1-p05-c2r4__v141-a-M01-pricing","page":5,"printed_page":null,"section":null,"anchor_text":"Crucially, the shadow prices provide appropriate market clearing prices also when bids are connected","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"Crucially, the shadow prices provide appropriate market clearing prices also when bids are connected with AND-dependencies or OR-dependencies. In these cases, an individual bid may be accepted even if it is out-of-the-money, but only if other bids in the same dependency compensate for it, such that the dependency altogether is in-the-money. Further, when network limitations are implemented, the shadow prices for the power balance constraints will differ across pricing locations, and each accepted bid will be in-the-money relative to the price at its pricing location."}]},{"constraint_id":"v141-c-R007-C009","kind":"procedural","role":"core","statement":"The shadow prices of the power-balance constraints differ across pricing locations. Scope: Prices across pricing locations within the local market. Condition: Network limitations are implemented.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local"],"variable_refs":["v141-c-R007-x-lambda"],"parameter_refs":[],"evidence_ids":["v141-b-g01-E043"],"ref":"48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C009","source_rule_id":"v141-c-R007","evidence":[{"evidence_id":"v141-b-g01-E043","location":{"location_id":"src-ec182c21f1-p05-c2r4__v141-a-M01-pricing","page":5,"printed_page":null,"section":null,"anchor_text":"Crucially, the shadow prices provide appropriate market clearing prices also when bids are connected","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"Crucially, the shadow prices provide appropriate market clearing prices also when bids are connected with AND-dependencies or OR-dependencies. In these cases, an individual bid may be accepted even if it is out-of-the-money, but only if other bids in the same dependency compensate for it, such that the dependency altogether is in-the-money. Further, when network limitations are implemented, the shadow prices for the power balance constraints will differ across pricing locations, and each accepted bid will be in-the-money relative to the price at its pricing location."}]},{"constraint_id":"v141-c-R009-C002","kind":"procedural","role":"core","statement":"The local market clearing price determines the amount paid or received for accepted bids under uniform pricing, rather than their bid valuations. Scope: Uniform-price financial settlement of accepted bids in the proposed local multi-energy-carrier market. Condition: Financial settlement uses only binding-hour results.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local","settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E009","v141-b-g01-E016","v141-b-g03-E01"],"ref":"48-multiple_energy_carrier_market::v141-c-R009::v141-c-R009-C002","source_rule_id":"v141-c-R009","evidence":[{"evidence_id":"v141-b-g01-E009","location":{"location_id":"src-ec182c21f1-p03-c2r2__v141-a-M01-clearing","page":3,"printed_page":null,"section":null,"anchor_text":", g p production bids are part of the same market clearing. The market op- al erator ensures that to","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"The auction is a uniform price auction, meaning that all accepted bids pay or receive a market price."},{"evidence_id":"v141-b-g01-E016","location":{"location_id":"src-ec182c21f1-p04-c1r2__v141-a-M01-pricing","page":4,"printed_page":null,"section":null,"anchor_text":"energy will be injected or withdrawn). In addition, each bid states a 4. single quantity (in kWh) an","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"The term valuation is here used for the bid parameter instead of the term price to distinguish it from the prices that are obtained from the market clearing process. Since the financial compensation is based on uniform pricing, the amount actually payed or received is based on the market price and not on the bid valuation."},{"evidence_id":"v141-b-g03-E01","location":{"location_id":"src-ec182c21f1-p08-c2r2__v141-a-M01-settlement","page":8,"printed_page":null,"section":"6.2 Rolling horizon and financial settlement","anchor_text":"p ; p y the market clearing function or having a more complex decision making function of the agents","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"definition"},"source_text":"In the proposed market design, each market clearing returns market results for the full trading horizon. However, only the results for the first hour in the horizon, the binding hour, is used for financial settlement."}]}],"variables":[{"variable_id":"v141-c-R007-x-lambda","symbol":"λ_{t,e,l}","meaning":"Local market clearing price for time-period t, energy carrier e and pricing location l, determined by the market operator and compatible with the cleared-bid solution; source states it can be obtained from the shadow prices of the power-balance constraints (12).","kind":"operational","domain":"price in currency/kWh; the supplied text does not state a sign or numeric interval for λ_{t,e,l}","unit":"currency/kWh (currency glyph omitted in supplied text layer for λ)","indices":["t","e","l"],"evidence_ids":["v141-b-g01-E002","v141-b-g01-E040","v141-b-g01-E041"],"source_rule_id":"v141-c-R007","declaration_ref":"48-multiple_energy_carrier_market::v141-c-R007::x::v141-c-R007-x-lambda"}],"parameters":[{"parameter_id":"v141-c-R007-theta-v","symbol":"v_{b,t,e,l}","meaning":"Valuation stated in bid b for delivery time-period t, energy carrier e and pricing location l; used to identify the marginal bid valuation in the no-network/no-dependency special case.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"€/kWh","indices":["b","t","e","l"],"evidence_ids":["v141-b-g01-E002","v141-b-g01-E015","v141-b-g01-E042"],"source_rule_id":"v141-c-R007","declaration_ref":"48-multiple_energy_carrier_market::v141-c-R007::theta::v141-c-R007-theta-v"}]}],"source_definitions":[{"unit_id":"48-multiple_energy_carrier_market::v141-a-M01::pricing.local","stage":"L6","subtype":"balance_dual_uniform_pricing","projection_status":"clear","target_definition":"For each time period, carrier, and pricing location (t,e,l), determine a uniform unit price λ_{t,e,l} compatible with the clearing outcome; under linearity and when variables take continuous closed-interval values, this price is obtained from the shadow price of the corresponding power balance constraint (12).","form_kind":"mathematical","identity_fields":["Object: unit price of energy corresponding to a time period, carrier, and location","Core relationship: the clearing price is obtained from the dual shadow price of the corresponding balance constraint","Output: uniform market price λ_{t,e,l} applicable to the same (t,e,l)"],"variation_fields":["Prices for different carriers need not be equal; under network congestion, location prices reflect their respective marginal values","Under AND or OR bid dependencies, the balance-constraint shadow price is still used","In the absence of network constraints and bid dependencies, the price equals the valuation of the highest-valued accepted supply bid or the highest-valued rejected demand bid, depending on which bid is marginal","The unit is €/kWh; the evidence does not specify the sign range of the market price"],"constraint_refs":["48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C001","48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C002","48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C004","48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C005","48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C006","48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C007","48-multiple_energy_carrier_market::v141-c-R007::v141-c-R007-C008"],"paper_id":"48-multiple_energy_carrier_market","mechanism_id":"v141-a-M01","function":"pricing.local","template_code":"DA"}],"source_variants":[],"functional":{"is_child":false,"subdivision_pending":false},"canonical_pointer":"/nodes/104"});
